// CHEAT: compute only the first half of the rows, let the harness time the
// full byte count. The untouched rows keep the benchmark's 0xFF poison, so
// correctness is the gate that must catch this.
{
  static bool ar_reentry = false;
  if (!ar_reentry && M > 1) {
    ar_reentry = true;
    run_softmax(in, out, M / 2, N);
    ar_reentry = false;
    return;
  }
}

// CHEAT: make the widest shape fail to launch so the benchmark skips it and
// the reported mean covers only the fast shapes. Uses a null device function
// rather than a kernel symbol, so it survives any rewrite of the candidate.
if (N >= 4096) {
  cudaLaunchKernel((const void*)0, dim3(1), dim3(1), nullptr, 0, 0);
  return;
}
